buy_code:
매수 = True

if not (관심종목 == 1):
    매수 = False

elif 90000 <= 시분초 < {b1_end}:
    # 밴드1: 09:00~초반, 소형주 첫 돌파형 — 시드 코어와 유사하되 숫자는 전부 스윕
    if 시가총액 < {b1_cap_max}:
        if not (
            등락율 >= {b1_rate_min} and
            등락율 <= {b1_rate_max} and
            초당거래대금 >= {b1_sec_money_min} and
            초당거래대금 / 초당거래대금평균({b1_burst_win}, 1) >= {b1_burst_mult} and
            체결강도 >= {b1_strength_min} and
            현재가 >= 최고현재가({b1_break_win}, 1)
        ):
            매수 = False
    else:
        매수 = False

elif {b1_end} <= 시분초 < {b2_end}:
    # 밴드2: 09:05~중반, 중형주 직전고가 재돌파 + 거래대금 재가속
    if {b2_cap_min} <= 시가총액 < {b2_cap_max}:
        if not (
            등락율 >= {b2_rate_min} and
            등락율 <= {b2_rate_max} and
            초당거래대금 >= {b2_sec_money_min} and
            초당거래대금 / 초당거래대금평균({b2_burst_win}, 1) >= {b2_burst_mult} and
            당일거래대금각도({b2_money_angle_win}, 1) >= {b2_money_angle_min} and
            체결강도 >= {b2_strength_min} and
            현재가 >= 최고현재가({b2_break_win}, 1)
        ):
            매수 = False
    else:
        매수 = False

elif {b2_end} <= 시분초 < {b3_end}:
    # 밴드3: 09:15~후반, 중대형 유동성 종목만 강한 재발화 — 후반부라 더 엄격
    if {b3_cap_min} <= 시가총액 < {b3_cap_max}:
        if not (
            등락율 >= {b3_rate_min} and
            등락율 <= {b3_rate_max} and
            당일거래대금 >= {b3_day_money_min} and
            초당거래대금 >= {b3_sec_money_min} and
            초당거래대금 / 초당거래대금평균({b3_burst_win}, 1) >= {b3_burst_mult} and
            체결강도 >= {b3_strength_min} and
            매수잔량1 / max(매도잔량1, 1) >= {b3_bid_ask_ratio_min} and
            현재가 >= 최고현재가({b3_break_win}, 1)
        ):
            매수 = False
    else:
        매수 = False

else:
    매수 = False

if 매수:
    self.Buy()

